# Let's create test images with potential triggers in different corners
# Patch types: white square, checkerboard, random noise
# Size: 3-5 pixels, placed 1 pixel from corner

def add_patch(img, corner='top_left', patch_type='white', size=4):
    """Add a patch to a clean image."""
    img = img.copy()
    h, w = img.shape[1], img.shape[2]

    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - size - 1
    elif corner == 'bottom_left':
        r, c = h - size - 1, 1
    elif corner == 'bottom_right':
        r, c = h - size - 1, w - size - 1
    else:
        raise ValueError(f"Unknown corner: {corner}")

    if patch_type == 'white':
        patch = np.ones((3, size, size), dtype=np.uint8) * 255
    elif patch_type == 'checkerboard':
        patch = np.zeros((3, size, size), dtype=np.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'random':
        patch = np.random.randint(0, 256, (3, size, size), dtype=np.uint8)
    else:
        raise ValueError(f"Unknown patch type: {patch_type}")

    img[:, r:r+size, c:c+size] = patch
    return img

